WITH customer_summary AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled, ROUND(STDDEV(monthly_fee), 2) AS stddev_monthly_fee FROM subscriptions GROUP BY customer_id) SELECT customers.id, customers.signup_date, customer_summary.pct_cancelled, customer_summary.stddev_monthly_fee FROM customers LEFT JOIN customer_summary ON customers.id = customer_summary.customer_id WHERE customer_summary.pct_cancelled > 52
